function uploadField(){
 uniforms.fieldX.value.image.data=field.textureData('x');uniforms.fieldX.value.needsUpdate=true;
 uniforms.fieldZ.value.image.data=field.textureData('z');uniforms.fieldZ.value.needsUpdate=true;
 uniforms.wind.value.set(field.cos,field.sin);uniforms.isWake.value=!!field.experimental;
 if(field.experimental){uniforms.pressureData.value.image.data=field.cp;uniforms.pressureData.value.needsUpdate=true;}
 rebuildPaths();updateMetrics();
}
function switchSolver(name){
 if(!idealField)return;wakeWorker?.terminate();wakeWorker=null;state.paused=false;wakeComplete=false;
 const wake=name==='wake';$('speed').disabled=$('yaw').disabled=wake;$('solverProgress').hidden=$('restartWake').hidden=!wake;$('solverProgress').value=0;
 document.querySelectorAll('[data-solver]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.solver===name)));
 $('solverNote').textContent=wake?'Re 500 · zero yaw · 2,000 steps. Startup transients are included.':'Steady, inviscid flow. No separation or drag prediction.';
 $('footerNote').textContent=wake?'Reduced-Re experiment · slip ground · stationary wheels':'Potential flow · slip ground · stationary wheels';
 if(!wake){$('yaw').value=state.yaw;field=idealField;field.setYaw(state.yaw);uploadField();$('status').textContent='Potential flow ready';setMode(state.mode);updateMetrics();return;}
 idealField.setYaw(0);field=new WakeField(idealField,0);$('yaw').value=0;uploadField();setMode('slice');$('yawOut').textContent='0°';$('speedOut').textContent='Re 500';$('status').textContent='Starting calculation';
 wakeWorker=new Worker('./wake-worker.js',{type:'module'});
 const stop=message=>{$('status').textContent='Calculation stopped';$('solverNote').textContent=message;state.paused=true;wakeComplete=true;updatePauseButton();wakeWorker?.terminate();wakeWorker=null;};
 wakeWorker.onmessage=({data})=>{
  if(data.type==='progress'){$('solverProgress').value=data.steps;$('status').textContent=(state.paused?'Paused · ':'Calculating · ')+data.steps.toLocaleString()+' / 2,000';}
  if(data.type==='frame'){field.update(data.data,data.steps);uploadField();$('solverProgress').value=data.steps;$('status').textContent=(state.paused?'Paused · ':'Viscous study · ')+data.steps.toLocaleString()+' / 2,000';}
  if(data.type==='error')stop(data.message);
  if(data.type==='complete'){wakeComplete=true;state.paused=true;$('status').textContent='2,000 steps · snapshot ready';$('solverNote').textContent='Calculation complete. Inspect or export the final field; restart to calculate again.';updatePauseButton();}
 };
 wakeWorker.onerror=()=>stop('Unable to run the local solver. Restart the calculation or select Potential.');
 wakeWorker.postMessage({type:'start',grid:field.grid,mask:field.solid,yaw:0,paused:document.hidden||state.mode==='inspect'});
 updatePauseButton();
}
function exportWake(){if(!field.steps){$('solverNote').textContent='Wait for the first snapshot before exporting.';return;}const rows=[['Giulia viscous research snapshot'],['Reynolds',500],['steps',field.steps],['yaw_degrees',0],['method','D3Q19 BGK Smagorinsky; unvalidated reduced-Re experiment'],['x_m','y_m','z_m','u_over_U','v_over_U','w_over_U','Cp']];for(let x=-4.5;x<7;x+=.25)for(let y=.25;y<3;y+=.25){const z=Number($('slice').value),v=field.sample(x,y,z);if(v)rows.push([x,y,z,...v,field.pressureAt(x,y,z)]);}const url=URL.createObjectURL(new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='giulia-wake-re500-step'+field.steps+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
start();


